package io.github.miklires.mreports;
import io.github.miklires.mreports.api.MReportsApi;import io.github.miklires.mreports.api.ReportView;import io.github.miklires.mreports.storage.ReportRepository;import java.util.List;import java.util.Optional;import java.util.UUID;import java.util.concurrent.CompletableFuture;
final class ReportsApiService implements MReportsApi {private final ReportRepository repository;private final long duplicateWindow;ReportsApiService(ReportRepository repository,long duplicateWindow){this.repository=repository;this.duplicateWindow=duplicateWindow;}public CompletableFuture<ReportView> submit(UUID a,String b,UUID c,String d,String e,String f){return repository.submit(a,b,c,d,e,f,duplicateWindow).thenApply(ReportRepository.Submission::report);}public CompletableFuture<Optional<ReportView>> find(long id){return repository.find(id);}public CompletableFuture<List<ReportView>> openReports(int limit){return repository.queue(limit);}public CompletableFuture<List<ReportView>> search(String query,int limit){return repository.search(query,limit);}public CompletableFuture<List<ReportView>> history(UUID playerId,int limit){return repository.history(playerId,limit);}}
